        [ "Inspection window", "Once the order is marked delivered, you have a configurable window (usually 2 days) to inspect the item and confirm receipt or open a dispute. Without action, the order completes automatically and the seller is paid." ],
        [ "Opening a dispute", "Open the order, select \"Open dispute\", choose a reason and attach photos. The seller may respond. If you cannot agree, our team reviews the evidence and may order a full or partial refund." ],
        [ "Timing", "Disputes are handled in order of arrival. Refunds may take several business days depending on your bank." ],
        [ "Contact", "Questions before buying: {{support_email}} or the help centre." ]
