    ),
    "seller_terms" => LegalSeed.page(
      "Seller terms",
      "These terms apply to anyone listing or selling on PCMarket, whether private or professional.",
      [
        [ "General obligations", [
          "Describe the item, condition and price accurately and completely.",
          "Have the right to sell the item and ensure it is lawful.",
          "Reply to messages and ship within the stated time.",
          "Pack properly and provide tracking where possible.",
          "Comply with tax, consumer and data protection rules."
        ] ],
        [ "Private and professional sellers", "You must state whether you sell privately or professionally. Professionals must provide their company name, tax ID and contact details, give the required pre-contractual information and honour legal guarantees. Private sellers may not present themselves as a business or issue invoices that do not belong to them." ],
        [ "Prohibited practices", [
          "Listing stolen, counterfeit or recalled products.",
          "Manipulating photos, descriptions or reviews.",
          "Requesting off-platform payments to bypass buyer protection.",
          "Creating multiple accounts to evade suspension."
        ] ],
        [ "Fees and payments", "Use is currently free, apart from featured services. We may introduce commissions with at least 30 days' notice. Funds are released after receipt is confirmed or the inspection window ends, less commission and agreed shipping." ],
        [ "DAC7 and tax information", "As a digital platform, PCMarket must collect and verify certain tax data and report sellers exceeding 30 sales or EUR 2,000 in a calendar year to the French tax authority (DGFiP). If you do not provide the data, we may limit your ability to sell." ],
        [ "Suspension", "We may suspend or close accounts for serious breaches, repeated issues or legal requirements. Amounts owed for confirmed orders are settled under these terms and the law." ]
      ]
    ),
    "prohibited_items" => LegalSeed.page(
      "Prohibited items",
      "To protect the community and comply with the law, certain items may not be listed on PCMarket. This list is indicative, not exhaustive.",
      [
        [ "Stolen or unlawful items", "Stolen, misappropriated or fraudulently obtained items, or items whose origin you cannot prove, are prohibited. We may remove the listing and report it to the authorities." ],
        [ "Counterfeits", "Counterfeits, replicas presented as genuine and any product infringing intellectual property rights are prohibited." ],
        [ "Recalled or unsafe products", "Products subject to a recall or safety alert, or that fail safety rules, are prohibited." ],
        [ "Locked devices", "Phones, tablets and computers with locked accounts, remote activation, iCloud, Google or corporate accounts preventing normal use are not accepted. Sellers must unlink all accounts before shipping." ],
        [ "Weapons and regulated items", "Firearms, ammunition, prohibited knives, explosives, fireworks, tear gas and any item requiring authorisation are prohibited." ],
        [ "Dangerous or illegal products", "Drugs, medicines, hazardous chemicals, radioactive materials, organs, protected species, identity documents, third-party personal data and malicious software are prohibited." ],
        [ "Services and content", "Illegal services, adult content, gambling, abusive lending, cryptocurrencies and pyramid schemes are prohibited." ],
        [ "Consequences", "We may remove the listing, suspend the account and report it to the authorities. If in doubt, contact {{support_email}} before listing." ]
      ]
