    "dsa_contact" => LegalSeed.page(
      "DSA contact and illegal content notices",
      "PCMarket complies with Regulation (EU) 2022/2065 on Digital Services (DSA). This page explains how to contact us and report allegedly illegal content.",
      [
        [ "Point of contact", "The single point of contact for authorities, users and third parties is {{legal_email}}. For support and consumer matters: {{support_email}}. We reply in the language of the communication or, failing that, in Spanish or English." ],
        [ "Reporting", "Anyone may report a listing, message or profile they consider illegal. Include the link or identifier, the reason, sufficient explanation and evidence where possible. Manifestly unfounded or abusive reports may be dismissed." ],
        [ "Handling", "We review reports without undue delay, take proportionate measures and inform you of the decision. If content is removed, the affected user receives a clear statement of reasons and may appeal." ],
        [ "Internal complaints", "Users may challenge moderation, suspension or removal decisions via the contact form or {{legal_email}}. A free internal complaint system is available for at least six months." ],
        [ "Out-of-court resolution", "You may use an accredited consumer mediation body. In France, the competent mediator is indicated by the professional seller. The EU online dispute resolution platform was discontinued in July 2025." ],
        [ "Transparency", "We publish aggregated moderation information where required by law. Relevant automated decisions are reviewed by a person where they affect user rights." ],
        [ "Postal contact", "{{company_legal_name}}, {{company_address}}. For formal notices, mark the subject \"DSA\"." ]
      ]
